    #[test]
    fn ribbon_sort_is_the_engines() {
        let mut x = 0x12345678u32;
        let mut r = || {
            x ^= x << 13;
            x ^= x >> 17;
            x ^= x << 5;
            x
        };
        for (case, &want) in SORTS.iter().enumerate() {
            let n = r() % 300;
            let depth = if r() % 3 == 0 { r() % 4 } else { n };
            let nk = 1 + r() % 8;
            let mut a: Vec<SortData> = (0..n).map(|i| (i, (((r() % 2) * (r() % 3)) as u64) << 32 | (0x3f800000 + r() % nk) as u64)).collect();
            qsort(&mut a, depth as i64);
            let h = a.iter().fold(0xcbf29ce484222325u64, |h, &(i, k)| ((h ^ i as u64).wrapping_mul(0x100000001b3) ^ k).wrapping_mul(0x100000001b3));
            assert_eq!(h, want, "sort {case}");
        }
    }

    #[test]
    fn trail_strips_are_the_engines() {
        let f = f32::from_bits;
        for (case, &(w, cx, cy, mode, wstate, wk, gstate, cmin, cmax, wf, cf, cm, points, expect)) in LINES.iter().enumerate() {
            let mut c = Trail { texture_mode: mode, ..Default::default() };
            c.width_over_trail.state = wstate;
            (c.width_over_trail.min_scalar, c.width_over_trail.scalar) = (f(wk[0]), f(wk[1]));
            c.color_over_trail.state = gstate;
            (c.color_over_trail.min_color, c.color_over_trail.max_color) = (cmin.map(f), cmax.map(f));
            let p = Params { width_multiplier: f(w), width_factor: f(wf), color_multiplier: cm, color_factor: f(cf) };
            let points: Vec<[f32; 3]> = points.iter().map(|p| p.map(f)).collect();
            let mut out = Vec::new();
            build_line(&mut out, &c, &points, p.width_multiplier, &View::unrotated([f(cx), f(cy), -10.0]), 0.0, |_| p);
            let got: Vec<[u32; 6]> = out.iter().map(|(q, color, uv)| [q[0].to_bits(), q[1].to_bits(), q[2].to_bits(), *color, uv[0].to_bits(), uv[1].to_bits()]).collect();
            assert_eq!(got, expect, "line {case}");
        }
    }
